    private static async Task<List<EventStream.RawEvent>> ParseAsync(string text)
    {
        EventStream.SseParser parser = new(
            new MemoryStream(Encoding.UTF8.GetBytes(text)),
            1024,
            null
        );
        List<EventStream.RawEvent> events = [];
        for (
            EventStream.RawEvent? next = await parser.NextAsync(default);
            next is not null;
            next = await parser.NextAsync(default)
        )
        {
            events.Add(next);
        }
        return events;
    }

    private static async Task<List<string>> LinesAsync(string text)
    {
        using JsonLinesStream<string> stream = new(
            Bytes(text),
            line => line,
            1024,
            "GET",
            "/items"
        );
        List<string> items = [];
        await foreach (string item in stream)
        {
            items.Add(item);
        }
        return items;
    }

    /// <summary>Opens an event stream whose n-th connection (from 1) is the n-th script entry.</summary>
    private sealed class Script(params object[] connections)
    {
        public List<string> LastIds { get; } = [];

        public Task<ByteStream> OpenAsync(string lastEventId, CancellationToken cancellationToken)
        {
            LastIds.Add(lastEventId);
            object next = connections[Math.Min(LastIds.Count, connections.Length) - 1];
            if (next is Exception failure)
            {
                return Task.FromException<ByteStream>(failure);
            }
            return Task.FromResult(next is ByteStream stream ? stream : Bytes((string)next));
        }
    }

    private static StreamOptions Fast()
    {
        return new StreamOptions { ReconnectDelay = 1 };
    }

    private static Task<SseStream<string>> SseAsync(
        Script script,
        StreamOptions options,
        bool hasBody = false
    )
    {
        return SseStream<string>.OpenAsync(
            script.OpenAsync,
            null,
            null,
            options,
            hasBody,
            hasBody ? "POST" : "GET",
            "/events",
            default
        );
    }

    private static async Task<List<string?>> DataOfAsync(SseStream<string> stream)
    {
        List<string?> data = [];
        await foreach (ServerSentEvent<string> item in stream)
        {
            data.Add(item.Data);
        }
        return data;
    }

