    [Fact]
    public async Task BhvStreaming004AJsonLinesLineThatDoesNotDecodeNamesItsLineAndEndsTheStream()
    {
        using JsonLinesStream<int> stream = new(
            Bytes("1\n2\nnope\n4\n"),
            line =>
                int.TryParse(
                    line,
                    System.Globalization.CultureInfo.InvariantCulture,
                    out int number
                )
                    ? number
                    : throw new SerializationException("not a number"),
            1024,
            "GET",
            "/items"
        );
        Assert.True(await stream.MoveNextAsync(default));
        Assert.Equal(1, stream.Current);
        Assert.True(await stream.MoveNextAsync(default));
        Assert.Equal(2, stream.Current);

        SerializationException failure = await Assert.ThrowsAsync<SerializationException>(
            async () =>
            {
                _ = await stream.MoveNextAsync(default);
            }
        );

        Assert.Contains("Line 3", failure.Message, StringComparison.Ordinal);
        Assert.False(await stream.MoveNextAsync(default), "the stream ended at the bad line");
    }

    [Fact]
    public async Task BhvStreaming005ALineOrEventLongerThanTheLimitRaisesASerializationErrorAndEndsTheStream()
    {
        using JsonLinesStream<string> lines = new(
            Bytes("ok\n" + new string('x', 50) + "\nlater\n"),
            line => line,
            10,
            "GET",
            "/items"
        );
        Assert.True(await lines.MoveNextAsync(default));
        Assert.Equal("ok", lines.Current);
        _ = await Assert.ThrowsAsync<SerializationException>(async () =>
        {
            _ = await lines.MoveNextAsync(default);
        });
        Assert.False(await lines.MoveNextAsync(default));

        await using SseStream<string> events = await SseAsync(
            new Script("data: " + new string('y', 50) + "\n\n"),
            new StreamOptions { MaxEventBytes = 10 }
        );
        _ = await Assert.ThrowsAsync<SerializationException>(() => DataOfAsync(events));
        Assert.Empty(await DataOfAsync(events));
    }

    [Fact]
    public async Task BhvSse001AnSseStreamYieldsTheIdEventDataAndRetryFieldsOfEachEventWithMessageAsTheDefault()
    {
        List<EventStream.RawEvent> events = await ParseAsync(
            "id: 7\nevent: tick\nretry: 250\ndata: one\n\ndata: two\n\n"
        );
        Assert.Equal(2, events.Count);
        Assert.Equal(new EventStream.RawEvent("7", "tick", "one", 250L), events[0]);
        Assert.Equal("message", events[1].Event);
        Assert.Equal("two", events[1].Data);
        Assert.Equal("7", events[1].Id);

        await using SseStream<string> stream = await SseAsync(
            new Script("id: 7\nevent: tick\nretry: 250\ndata: one\n\n"),
            Fast()
        );
        ServerSentEvent<string> first = (await stream.AdvanceAsync(default))!;
        Assert.Equal("7", first.Id);
        Assert.Equal("tick", first.Event);
        Assert.Equal("one", first.Data);
        Assert.Equal(250L, first.Retry);
        Assert.Equal("one", first.Raw);
    }

